def compute(vars):
    old_equity = vars["v1"]
    cet1 = vars["v2"]

    if old_equity == 0:
        return {"value": None, "trace": {}}

    change = cet1 - old_equity
    change_ratio = change / old_equity
    percentage_change = change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "old_equity": old_equity,
            "cet1": cet1,
            "change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
